def loan_payment(principal, annual_rate, years):
    months = years * 12
    if annual_rate == 0:
        return principal / months
    monthly_rate = annual_rate / (100 * 12)
    R = (1 + monthly_rate) ** months
    return round((principal * monthly_rate * R) / (R - 1), 2)

